import re
def parse_math_problem(text):
    nums = list(map(int, re.findall(r'\d+', text)))
    ops = re.findall(r'[+\-*/]', text)
    return {'numbers': nums, 'operators': ops}
def cot_reasoning(problem):
    parsed = parse_math_problem(problem)
    steps = []
    if '+' in problem:
        total = sum(parsed['numbers'])
        for n in parsed['numbers']:
            steps.append(f'当前数字: {n}')
        steps.append(f'相加得: {total}')
    return {'steps': steps, 'answer': total if '+' in problem else None}
def verify_answer(steps, expected):
    return steps.get('answer') == expected if isinstance(steps, dict) else False

def think(state, tools):
    if not state['steps']:
        return 'search'
    last = state['steps'][-1]
    if 'result:' in last:
        return 'answer'
    return 'search'
def act(action, tools):
    if action in tools:
        return tools[action]()
    return f'unknown action: {action}'
def react_agent(task, tools, max_steps=5):
    state = {'task': task, 'steps': []}
    for _ in range(max_steps):
        action = think(state, tools)
        if action == 'answer':
            return {'answer': state['steps'][-1], 'steps': state['steps']}
        obs = act(action, tools)
        state['steps'].append(f'{action} -> {obs}')
    return {'answer': 'max steps reached', 'steps': state['steps']}

