def kl_divergence(p, q):
    p_sft = np.exp(p - np.max(p)); p_sft /= np.sum(p_sft)
    q_sft = np.exp(q - np.max(q)); q_sft /= np.sum(q_sft)
    return float(np.sum(p_sft * np.log(p_sft / (q_sft + 1e-10) + 1e-10)))
