import numpy as np
def euclidean(a,b):return float(np.sqrt(np.sum((a-b)**2)))
def hnsw_search(query,nodes,levels,top_k=3):
    n=len(nodes)
    for level in reversed(range(levels)):
        candidates=list(range(n)) if level==0 else list(range(0,n,2**(level+1)))
        if not candidates:candidates=list(range(n))
        dists=[(euclidean(query,nodes[i]),i)for i in candidates]
        dists.sort(key=lambda x:x[0])
        nearest=dists[:top_k]
    nearest.sort(key=lambda x:x[0])
    return [int(i)for _,i in nearest]

import numpy as np
def cosine_sim(a,b):
  return float(a@b/(np.linalg.norm(a)*np.linalg.norm(b)+1e-10))
def retrieve(query,docs,top_k=2):
  sc=[(cosine_sim(query,d[1]),d)for d in docs]
  sc.sort(key=lambda x:-x[0])
